svg.script:
//!export-start
var _pb_running=false;
//!export-end
function postValue(id,v){console.log('FUXA post:',id,'=',v);}
function putValue(id,v){
  if(id==='_pb_running'){
    _pb_running=v!==0;
    document.getElementById('static-img').style.display=_pb_running?'none':'inline';
    document.getElementById('anim-gif').style.display=_pb_running?'inline':'none';
  }
}
var o=new MutationObserver(function(m){m.forEach(function(mu){mu.removedNodes.forEach(function(n){if(n.id==='fuxa-dyn-auger_rh_right_slow'){o.disconnect();}});});});
o.observe(document.body,{childList:true,subtree:true});
